// SubmitFeedback is the resolver for the submitFeedback field.
func (r *mutationResolver) SubmitFeedback(ctx context.Context, input model.SubmitFeedbackInput) (*model.UserFeedback, error) {
	userID, ok := middleware.GetUserID(ctx)
	if !ok {
		return nil, fmt.Errorf("user not authenticated")
	}

	// Validate message length
	const maxMessageLength = 2000
	if len(input.Message) > maxMessageLength {
		return nil, fmt.Errorf("feedback message is too long (max %d characters)", maxMessageLength)
	}

	// Rate limit check: max 3 submissions per 24 hours
	since := pgtype.Timestamptz{Time: time.Now().Add(-24 * time.Hour), Valid: true}
	count, err := r.DB.Queries.GetRecentFeedbackCount(ctx, sqlc.GetRecentFeedbackCountParams{
		Userid: userID,
		Since:  since,
	})
	if err != nil {
		return nil, fmt.Errorf("failed to check rate limit: %w", err)
	}
	if count >= 50 {
		return nil, fmt.Errorf("you can only submit 50 feedback messages per day")
	}

	// Generate new feedback ID
	feedbackID := ulid.NewUserFeedbackID()

	// Handle optional fields
	appVersion := ""
	if input.Device.AppVersion != nil {
		appVersion = *input.Device.AppVersion
	}
	locale := ""
	if input.Device.Locale != nil {
		locale = *input.Device.Locale
	}
	timezone := ""
	if input.Device.Timezone != nil {
		timezone = *input.Device.Timezone
	}
	contextUrl := ""
	if input.Device.ContextURL != nil {
		contextUrl = *input.Device.ContextURL
	}
	projectID := ""
	if input.ProjectID != nil {
		projectID = *input.ProjectID
	}
	tags := []string{}
	if input.Tags != nil {
		tags = input.Tags
	}

	// Create feedback entry
	feedback, err := r.DB.Queries.CreateUserFeedback(ctx, sqlc.CreateUserFeedbackParams{
		ID:           feedbackID,
		Userid:       userID,
		Message:      input.Message,
		Cancontactme: input.CanContactMe,
		Useragent:    input.Device.UserAgent,
		Platform:     input.Device.Platform,
		Screenwidth:  int32(input.Device.ScreenWidth),
		Screenheight: int32(input.Device.ScreenHeight),
		Appversion:   appVersion,
		Locale:       locale,
		Projectid:    projectID,
		Timezone:     timezone,
		Contexturl:   contextUrl,
		Tags:         tags,
	})
	if err != nil {
		return nil, fmt.Errorf("failed to create feedback: %w", err)
	}

	// Notify Firestore listeners about new feedback
	go r.FirebaseService.NotifyAdminFeedback(context.Background())

	return feedbackRowToModel(feedback), nil
}

